planBuild details:

```js
export async function planBuild(opts, cwd = process.cwd()) {
  const srcDir = ..., outDir = ..., manifestPath = ...;
  const sources = await walk(srcDir, srcDir);
  const manifest = (await loadManifest(manifestPath)) ?? emptyManifest();

  // read all source bytes once
  const contents = new Map();
  for (const rel of sources) contents.set(rel, await readFile(path.join(srcDir, rel)));

  const keys = new Map(sources.map(rel => [rel, fingerprint(contents.get(rel))]));

  // deps
  const deps = new Map();
  for (const rel of sources) {
    const ext = extname(rel);
    const resolved = {};
    for (const spec of readDeps(contents.get(rel), ext)) {
      const target = resolveDep(rel, spec);
      if (target) resolved[target] = keys.get(target) ?? MISSING;
    }
    deps.set(rel, resolved);
  }
```

