```js
// lib/transform.js
import path from 'node:path';
import { createHash } from 'node:crypto';
import { resolveDep, URL_RE } from './graph.js';

export function sha1(input) {...}
export function hashedName(rel, bytes) {...}

export function transformFile(rel, bytes, read) {
  const ext = path.posix.extname(rel);
  if (ext === '.js' || ext === '.mjs') {
    const text = bytes.toString('utf8');
    return { output: Buffer.from(`${text.trimEnd()}\n//# build ${sha1(text).slice(0,8)}\n`), assets: [] };
  }
  if (ext === '.css') {
    const text = bytes.toString('utf8');
    const names = new Map();
    const assets = [];
    for (const match of text.matchAll(URL_RE)) {
      const target = match[1];
      const relTarget = resolveDep(rel, target);
      if (!relTarget) continue;  // remote/absolute left as-is
      const depBytes = read(relTarget);
      if (!depBytes) continue;   // missing target: leave url as written
      const name = hashedName(relTarget, depBytes);
      names.set(target, name);
      assets.push({ name, bytes: depBytes });
    }
    return { output: Buffer.from(text.replace(URL_RE, (whole, target) => names.has(target) ? `url(${names.get(target)})` : whole)), assets };
  }
  if (ext === '.json') {
    const own = JSON.parse(bytes.toString('utf8'));
    let merged = own;
    if (own && typeof own.extends === 'string') {
      const relBase = resolveDep(rel, own.extends);
      const baseBytes = relBase ? read(relBase) : null;
      if (baseBytes) {
        const base = JSON.parse(baseBytes.toString('utf8'));
        const { extends: dropped, ...rest } = own;
        merged = { ...base, ...rest };
      }
    }
    return { output: Buffer.from(`${JSON.stringify(merged, null, 2)}\n`), assets: [] };
  }
  return { output: Buffer.from(bytes), assets: [] };
}
```

