```js
import { watch as fsWatch } from 'node:fs';
import path from 'node:path';

export async function watchBuild(opts, { cwd = process.cwd(), onReport, onError, debounceMs = 60 } = {}) {
  const srcDir = path.resolve(cwd, opts.src);
  let timer = null;
  let running = false;
  let pending = false;

  const runOnce = async () => {
    if (running) { pending = true; return; }
    running = true;
    try {
      const report = await build(opts, cwd);
      onReport(report);
    } catch (e) { onError(e); }
    finally {
      running = false;
      if (pending) { pending = false; schedule(); }
    }
  };
  const schedule = () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => { timer = null; runOnce(); }, debounceMs);
  };
  await runOnce();  // initial
  const watcher = fsWatch(srcDir, { recursive: true }, () => schedule());
  ...
}
```

