import { readFile, writeFile, rename, readdir, rm } from 'node:fs/promises';
import path from 'node:path';

export const MANIFEST_VERSION = 2;

const TMP_SUFFIX = '.tmp';

export async function loadManifest(file) {
  await dropStaleTemps(file);
  try {
    const parsed = JSON.parse(await readFile(file, 'utf8'));
    return parsed && parsed.version === MANIFEST_VERSION && parsed.files && typeof parsed.files === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

async function dropStaleTemps(file) {
  const dir = path.dirname(file);
  const prefix = `${path.basename(file)}.tmp-`;
  let names;
  try { names = await readdir(dir); } catch { return; }
  await Promise.all(names.filter(n => n.startsWith(prefix)).map(n => rm(path.join(dir, n), { force: true }).catch(() => {})));
}

export async function saveManifest(file, manifest) {
  const dir = path.dirname(file);
  const tmp = path.join(dir, `${path.basename(file)}.tmp-${process.pid}-${Date.now()}`);
  await mkdir(dir, { recursive: true });
  await writeFile(tmp, `${JSON.stringify(manifest, null, 2)}\n`);
  await rename(tmp, file);
}
