  if (ext === '.json') {
    try {
      const parsed = JSON.parse(await readFile(abs, 'utf8'));
      return typeof parsed?.extends === 'string' ? [parsed.extends] : [];
    } catch {
      return [];
    }
  }
  return [];
}
```

