===== lib\cache.js =====
export function cacheKey(stat) {
  return `${stat.size}:${Math.round(stat.mtimeMs)}`;
}

===== lib\graph.js =====
import { readFile } from 'node:fs/promises';

const IMPORT_RE = /import\s+(?:[^'"\n]*?\s+from\s+)?['"]([^'"]+)['"]/g;

function collect(re, text) {
  const found = [];
  let match;
  while ((match = re.exec(text)) !== null) found.push(match[1]);
  return found;
}

export async function readDeps(abs, ext) {
  if (ext !== '.js' && ext !== '.mjs') return [];
  const text = await readFile(abs, 'utf8');
  return collect(IMPORT_RE, text);
}

===== lib\manifest.js =====
import { readFile, writeFile } from 'node:fs/promises';

export const MANIFEST_VERSION = 2;

export async function loadManifest(file) {
  try {
    const parsed = JSON.parse(await readFile(file, 'utf8'));
    return parsed && parsed.version === MANIFEST_VERSION ? parsed : null;
  } catch {
    return null;
  }
}

export async function saveManifest(file, manifest) {
  await writeFile(file, `${JSON.stringify(manifest, null, 2)}\n`);
}

===== bin\build.js =====
#!/usr/bin/env node
import { build, parseArgs, USAGE } from '../lib/build.js';

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (opts.help) {
    process.stdout.write(USAGE);
    return 0;
  }
  const report = await build(opts);
  if (opts.json) {
    process.stdout.write(`${JSON.stringify(report)}\n`);
  } else {
    process.stdout.write(
      `built ${report.built.length}, skipped ${report.skipped.length}, removed ${report.removed.length} in ${report.durationMs}ms\n`,
    );
  }
  return 0;
}

main().then(
  (code) => {
    process.exitCode = code;
  },
  (error) => {
    process.stderr.write(`build failed: ${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
  },
);

