import { watch as watchFs } from 'node:fs';
import { readdir } from 'node:fs/promises';
import path from 'node:path';
import { build } from './build.js';

const DEBOUNCE_MS = 100;

export async function startWatch(opts, { cwd = process.cwd(), onReport, onError } = {}) {
  const srcDir = path.resolve(cwd, opts.src);
  let closed = false;
  let timer = null;
  let queue = Promise.resolve();

  const run = () => { queue = queue.then(async () => { try { onReport?.(await build(opts, cwd)); } catch (e) { onError?.(e); } }); return queue; };

  let watcher;
  try {
    watcher = watchFs(srcDir, { recursive: true }, () => { if (timer) clearTimeout(timer); timer = setTimeout(() => { timer = null; run(); }, DEBOUNCE_MS); });
  } catch (error) { throw new Error(`watch failed for ${srcDir}: ${error.message}`); }
  watcher.on('error', (error) => onError?.(error));

  await run();  // initial build (respects --dry-run)
  return {
    close() { closed = true; if (timer) clearTimeout(timer); watcher.close(); return queue; },
    get closed() { return closed; },
  };
}
```
