===== bin/build.js =====
#!/usr/bin/env node
import { build, parseArgs, USAGE } from '../lib/build.js';
import { startWatch } from '../lib/watch.js';

function describe(report) {
  return `built ${report.built.length}, skipped ${report.skipped.length}, removed ${report.removed.length} in ${report.durationMs}ms\n`;
}

function writeReport(report, opts) {
  process.stdout.write(opts.json ? `${JSON.stringify(report)}\n` : describe(report));
}

function writeError(error) {
  process.stderr.write(`build failed: ${error instanceof Error ? error.message : String(error)}\n`);
}

async function runWatch(opts) {
  const handle = await startWatch(opts, {
    onReport: (report) => writeReport(report, opts),
    onError: writeError,
  });
  process.stdout.write(`watching ${opts.src}\n`);
  await new Promise((resolve) => {
    const stop = () => handle.close().then(resolve, resolve);
    process.once('SIGINT', stop);
    process.once('SIGTERM', stop);
  });
  return 0;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (opts.help) {
    process.stdout.write(USAGE);
    return 0;
  }
  if (opts.watch) return runWatch(opts);
  writeReport(await build(opts), opts);
  return 0;
}

main().then(
  (code) => {
    process.exitCode = code;
  },
  (error) => {
    writeError(error);
    process.exitCode = 1;
  },
);

===== lib\fingerprint.js =====
import { createHash } from 'node:crypto';

export function hashBytes(bytes) {
  return createHash('sha1').update(bytes).digest('hex');
}

export function shortHash(bytes) {
  return hashBytes(bytes).slice(0, 8);
}

// Content fingerprint: independent of mtime, size and rewrite history.
export function contentKey(bytes) {
  return `sha1:${hashBytes(bytes)}`;
}

===== lib\graph.js =====
const IMPORT_RE = /import\s+(?:[^'"\n]*?\s+from\s+)?['"]([^'"]+)['"]/g;
export const URL_RE = /url\(\s*['"]?([^'")]+)['"]?\s*\)/g;

function collect(re, text) {
  const found = [];
  let match;
  while ((match = re.exec(text)) !== null) found.push(match[1]);
  return found;
}

// Specifiers a source file pulls in, per extension. Takes bytes so callers that
// already read the file (fingerprinting) do not pay for a second read.
export function readDeps(bytes, ext) {
  if (ext === '.js' || ext === '.mjs') return collect(IMPORT_RE, bytes.toString('utf8'));
  if (ext === '.css') return collect(URL_RE, bytes.toString('utf8'));
  if (ext === '.json') {
    let parsed;
    try {
      parsed = JSON.parse(bytes.toString('utf8'));
    } catch {
      return [];
    }
    return parsed && typeof parsed.extends === 'string' ? [parsed.extends] : [];
  }
  return [];
}

===== lib\manifest.js =====
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

export const MANIFEST_VERSION = 2;

export async function loadManifest(file) {
  try {
    const parsed = JSON.parse(await readFile(file, 'utf8'));
    return parsed && parsed.version === MANIFEST_VERSION ? parsed : null;
  } catch {
    return null;
  }
}

// Write to a sibling temp file and rename over the target, so an interrupted
// build can never leave a half-written manifest behind.
export async function saveManifest(file, manifest) {
  const dir = path.dirname(file);
  await mkdir(dir, { recursive: true });
  const tmp = path.join(dir, `.${path.basename(file)}.${process.pid}.tmp`);
  try {
    await writeFile(tmp, `${JSON.stringify(manifest, null, 2)}\n`);
    await rename(tmp, file);
  } catch (error) {
    await rm(tmp, { force: true });
    throw error;
  }
}

===== lib\cache.js =====
export function cacheKey(stat) {
  return `${stat.size}:${Math.round(stat.mtimeMs)}`;
}

===== lib\pool.js =====
// Run `worker` over `items` with at most `limit` in flight. Results come back in
// input order, so output bytes and report order never depend on the limit.
export async function mapLimit(items, limit, worker) {
  const list = [...items];
  const results = new Array(list.length);
  if (list.length === 0) return results;
  const width = Math.max(1, Math.min(Number.isFinite(limit) ? Math.floor(limit) : list.length, list.length));
  let cursor = 0;
  const runners = Array.from({ length: width }, async () => {
    for (;;) {
      const index = cursor;
      cursor += 1;
      if (index >= list.length) return;
      results[index] = await worker(list[index], index);
    }
  });
  await Promise.all(runners);
  return results;
}

===== lib\watch.js =====
import { watch as watchFs } from 'node:fs';
import path from 'node:path';
import { build } from './build.js';

const DEBOUNCE_MS = 100;

// Initial build, then one rebuild per settled burst of source changes. Rebuilds
// are serialised so overlapping bursts never race on the output tree.
export async function startWatch(opts, { cwd = process.cwd(), onReport, onError } = {}) {
  const srcDir = path.resolve(cwd, opts.src);
  let timer = null;
  let queue = Promise.resolve();

  const run = () => {
    queue = queue.then(async () => {
      try {
        const report = await build(opts, cwd);
        onReport?.(report);
        return report;
      } catch (error) {
        onError?.(error);
        return null;
      }
    });
    return queue;
  };

  const watcher = watchFs(srcDir, { recursive: true }, () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      run();
    }, DEBOUNCE_MS);
  });
  watcher.on('error', (error) => onError?.(error));

  await run();

  return {
    close() {
      if (timer) clearTimeout(timer);
      timer = null;
      watcher.close();
      return queue;
    },
  };
}

