import path from 'node:path';

const SCHEME_RE = /^[a-zA-Z][a-zA-Z0-9+.-]*:/;

// A specifier that can never name a file in the source tree: a url scheme
// (data:, http:), an absolute path, a protocol-relative or root path, a
// fragment, or a query-only reference.
function isOpaque(spec) {
  return SCHEME_RE.test(spec) || spec.startsWith('/') || spec.startsWith('#') || spec.startsWith('?');
}

// CSS url() targets are always relative to the stylesheet, so `img.png` and
// `./img.png` mean the same file. Every other kind of specifier has to opt in
// with a leading `.` — bare imports are packages, not files.
const BARE_OK = new Set(['.css']);

export function resolveDep(fromRel, spec, ext) {
  if (isOpaque(spec)) return null;
  if (!spec.startsWith('.') && !BARE_OK.has(ext)) return null;
  const dir = path.posix.dirname(fromRel);
  const resolved = path.posix.normalize(path.posix.join(dir === '.' ? '' : dir, spec));
  if (resolved.startsWith('../') || resolved === '..' || path.posix.isAbsolute(resolved)) return null;
  return resolved;
}
```

